CREATE TABLE media_directory (id CHAR(36) PRIMARY KEY,owner_id BIGINT NOT NULL,external_key VARCHAR(255) NOT NULL,name VARCHAR(512) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_media_directory UNIQUE(owner_id,external_key));
CREATE TABLE media_item (id CHAR(36) PRIMARY KEY,owner_id BIGINT NOT NULL,asset_id CHAR(36) NOT NULL,directory_id CHAR(36),source_type VARCHAR(64) NOT NULL,source_business_id VARCHAR(255) NOT NULL,display_name VARCHAR(512) NOT NULL,mime_type VARCHAR(255) NOT NULL,size_bytes BIGINT NOT NULL,content_sha256 CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,version BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_media_item_owner_asset UNIQUE(owner_id,asset_id),CONSTRAINT uk_media_item_source UNIQUE(owner_id,source_type,source_business_id),CONSTRAINT fk_media_item_directory FOREIGN KEY(directory_id) REFERENCES media_directory(id));
CREATE TABLE media_tag (id CHAR(36) PRIMARY KEY,owner_id BIGINT NOT NULL,name VARCHAR(128) NOT NULL,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_media_tag UNIQUE(owner_id,name));
CREATE TABLE media_tag_relation (media_item_id CHAR(36) NOT NULL,tag_id CHAR(36) NOT NULL,source VARCHAR(64) NOT NULL,confidence DECIMAL(6,5),analysis_version VARCHAR(64),created_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(media_item_id,tag_id,source),CONSTRAINT fk_media_tag_item FOREIGN KEY(media_item_id) REFERENCES media_item(id),CONSTRAINT fk_media_tag_tag FOREIGN KEY(tag_id) REFERENCES media_tag(id));
CREATE TABLE media_analysis (id CHAR(36) PRIMARY KEY,media_item_id CHAR(36) NOT NULL,analysis_version VARCHAR(64) NOT NULL,task_instance_id CHAR(36) NOT NULL,status VARCHAR(32) NOT NULL,result_sha256 CHAR(64),summary VARCHAR(2000),description TEXT,error_code VARCHAR(128),created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_media_analysis_version UNIQUE(media_item_id,analysis_version),CONSTRAINT uk_media_analysis_task UNIQUE(task_instance_id),CONSTRAINT fk_media_analysis_item FOREIGN KEY(media_item_id) REFERENCES media_item(id));
CREATE TABLE media_artifact (id CHAR(36) PRIMARY KEY,media_item_id CHAR(36) NOT NULL,asset_id CHAR(36) NOT NULL,artifact_kind VARCHAR(64) NOT NULL,generator_version VARCHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_media_artifact UNIQUE(media_item_id,artifact_kind,generator_version),CONSTRAINT fk_media_artifact_item FOREIGN KEY(media_item_id) REFERENCES media_item(id));
CREATE TABLE playback_progress (owner_id BIGINT NOT NULL,media_item_id CHAR(36) NOT NULL,position_ms BIGINT NOT NULL,duration_ms BIGINT NOT NULL,completed BOOLEAN NOT NULL,revision BIGINT NOT NULL,client_updated_at TIMESTAMP(6) NOT NULL,server_updated_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(owner_id,media_item_id),CONSTRAINT fk_playback_item FOREIGN KEY(media_item_id) REFERENCES media_item(id));
CREATE TABLE media_event_inbox (event_id VARCHAR(255) PRIMARY KEY,event_type VARCHAR(128) NOT NULL,payload_sha256 CHAR(64) NOT NULL,processed_at TIMESTAMP(6) NOT NULL);
CREATE TABLE media_task_binding (media_item_id CHAR(36) NOT NULL,task_instance_id CHAR(36) NOT NULL,purpose VARCHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(media_item_id,task_instance_id));
CREATE TABLE media_outbox (id CHAR(36) PRIMARY KEY,aggregate_type VARCHAR(64) NOT NULL,aggregate_id CHAR(36) NOT NULL,event_type VARCHAR(128) NOT NULL,payload_json TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,published_at TIMESTAMP(6));
